# Móveis ilustrados (vista 3/4, sombreado, sombra no chão). Uso: python3 tools/furn.py -> img/furn/*.svg
def lit(h,k):
    h=h.lstrip('#'); r,g,b=[int(h[i:i+2],16) for i in (0,2,4)]
    f=lambda c:max(0,min(255,int(c+(255-c)*k if k>0 else c*(1+k)))); return '#%02x%02x%02x'%(f(r),f(g),f(b))
def box(x,y,w,h,d,c,r=2):
    # frente (x,y,w,h) + tampo em profundidade d (para cima) + lateral direita
    return (f'<path d="M{x},{y} L{x+d*.5},{y-d} L{x+w+d*.5},{y-d} L{x+w},{y}Z" fill="{lit(c,.28)}"/>'
            f'<path d="M{x+w},{y} L{x+w+d*.5},{y-d} L{x+w+d*.5},{y+h-d} L{x+w},{y+h}Z" fill="{lit(c,-.32)}"/>'
            f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}"/><rect x="{x}" y="{y+h-3}" width="{w}" height="3" fill="#000" opacity=".15"/>')
def shadow(cx,cy,rx,ry=None): return f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry or rx*.22}" fill="#000" opacity=".28"/>'
def svg(w,h,body): return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" width="{w}" height="{h}"><defs><linearGradient id="gl" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".6"/><stop offset=".5" stop-color="#fff" stop-opacity="0"/></linearGradient></defs>{body}</svg>'
